function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(75001);
var T0=Date.now();
var L=24,P=6;
var hist=[];for(var i=0;i<L;i++)hist.push(100*Math.pow(1.08,i)*(0.95+R()*0.1));
var n=L-P,sx=0,sy=0,sxx=0,sxy=0;
for(var i=0;i<n;i++){var x=i,y=Math.log(hist[i]);sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}
var slope=(n*sxy-sx*sy)/(n*sxx-sx*sx),icept=(sy-slope*sx)/n;
var ape=0;for(var i=n;i<L;i++){var pred=Math.exp(icept+slope*i);ape+=Math.abs(pred-hist[i])/hist[i];}
var fc=[];for(var i=L;i<L+2;i++)fc.push(Math.round(Math.exp(icept+slope*i)));
console.log(JSON.stringify({id:"JAH-APX75-000001",ok:true,metrics:{history:L,held_out:P,mape_pct:+((ape/P)*100).toFixed(2),growth_per_period_pct:+((Math.exp(slope)-1)*100).toFixed(2),next_forecast:fc[0]},ms:Date.now()-T0}));

